-- 94: Southeast fishing rules (US plan step 4): Georgia, Alabama, South Carolina, North Carolina, Mississippi.
-- Checked 2026-10-21 against each state's own pages / 2026-27 guides (links in source_url). A state rule is a normal fish_rules row whose
-- `regions` holds the 2-letter state code (e.g. {GA}). The app keeps these apart from the Florida rows (js/10), so Florida is unchanged.
-- One row per species per state; lake-by-lake exceptions live in the note, and every rule still says "confirm with <agency>".
-- The connector refuses 'drop constraint', so Richard pastes this file into the Supabase SQL Editor (Run) BEFORE the v157 app is live.

alter table fish_rules drop constraint if exists fish_rules_regions_ok;
alter table fish_rules add constraint fish_rules_regions_ok
  check (regions is null or regions <@ array['atlantic','keys','gulf','spz','sw','ch','bigbend',
    'AL','AR','AZ','CA','CO','CT','DC','DE','GA','IA','ID','IL','IN','KS','KY','LA','MA','MD','ME','MI','MN','MO','MS','MT',
    'NC','ND','NE','NH','NJ','NM','NV','NY','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VA','VT','WA','WI','WV','WY']::text[]);

insert into fish_rules (species, match, regions, min_in, max_in, measure, one_over, bag, release_only, closed, open_only, note, source_url, verified_on, active) values
